// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Schema migration test – a database created by the first schema version keeps its simulation state
//          (moved to the view column) and its snapshots get kinds.

import { mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { DatabaseSync } from 'node:sqlite'
import { afterEach, expect, it } from 'vitest'
import { openDatabase } from './db.server'
import { createProjectStore } from './projects.server'

const dirs: string[] = []
afterEach(() => {
  for (const dir of dirs.splice(0)) rmSync(dir, { recursive: true, force: true })
})

it('upgrades a schema-1 database: ll.sim moves to the view state, snapshots get kinds', () => {
  const dir = mkdtempSync(join(tmpdir(), 'table-maker-'))
  dirs.push(dir)
  const file = join(dir, 'old.db')

  const old = new DatabaseSync(file)
  old.exec(`
    CREATE TABLE projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, data TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1,
      created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
    CREATE TABLE snapshots (id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, label TEXT NOT NULL,
      auto INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL, created_at TEXT NOT NULL);
    CREATE INDEX snapshots_project ON snapshots(project_id, created_at);
    PRAGMA user_version = 1;
  `)
  const v1 = JSON.stringify({
    app: 'ifj26-table-maker',
    version: 1,
    ll: { grammar: 'S -> a', input: 'a', sim: { step: 5, speed: 2 } },
    prec: { terminals: [], cells: {}, rules: '', input: '', gen: { levels: '', ids: '', parens: '' } },
  })
  const ts = '2026-01-01T10:00:00.000Z'
  old.prepare('INSERT INTO projects VALUES (?, ?, ?, 4, ?, ?)').run('p1', 'Starý', v1, ts, ts)
  old.prepare('INSERT INTO projects VALUES (?, ?, ?, 1, ?, ?)').run('p2', 'Bez simulácie', '{}', ts, ts)
  const snap = old.prepare('INSERT INTO snapshots (project_id, label, auto, data, created_at) VALUES (?, ?, ?, ?, ?)')
  snap.run('p1', 'Automatická záloha', 1, v1, ts)
  snap.run('p1', 'Moja verzia', 0, v1, ts)
  snap.run('p1', 'Pred obnovením „Moja verzia“', 0, v1, ts)
  snap.run('p1', 'Pred importom x.json', 0, v1, ts)
  old.close()

  const store = createProjectStore(openDatabase(file))
  const project = store.getProject('p1')!
  expect(project.view).toEqual({ llSim: { step: 5, speed: 2 } })
  expect(project.revision).toBe(4)
  expect(project.data.ll).toEqual({ grammar: 'S -> a', input: 'a' })
  expect(store.getProject('p2')!.view).toEqual({ llSim: { step: 0, speed: 1 } })
  expect(store.listSnapshots('p1').map((s) => [s.label, s.kind])).toEqual([
    ['Pred importom x.json', 'safety'],
    ['Pred obnovením „Moja verzia“', 'safety'],
    ['Moja verzia', 'named'],
    ['Automatická záloha', 'auto'],
  ])
})
